class Solution {
  public int numberOfAlternatingGroups(int[] colors, int k) {
    int n = colors.length;
    if (k == 1) return n;
    int answer = 0, run = 1;
    for (int i = 1; i < n + k - 1; i++) {
      if (colors[i % n] != colors[(i - 1) % n]) run++;
      else run = 1;
      if (i >= k - 1 && run >= k) answer++;
    }
    return answer;
  }
}
